    first_convolution_U0_ap_continue <= ap_const_logic_1;
    first_convolution_U0_ap_start <= start_for_first_convolution_U0_empty_n;
    first_convolution_U0_sums0_fifo_cap <= std_logic_vector(IEEE.numeric_std.resize(unsigned(std_logic_vector(IEEE.numeric_std.resize(unsigned(sums0_fifo_cap),3))),32));
    first_convolution_U0_sums0_num_data_valid <= std_logic_vector(IEEE.numeric_std.resize(unsigned(std_logic_vector(IEEE.numeric_std.resize(unsigned(sums0_num_data_valid),3))),32));
    reorg_quantize_U0_ap_continue <= ap_const_logic_1;
    reorg_quantize_U0_ap_start <= ap_start;
    reorg_quantize_U0_pixels0_fifo_cap <= std_logic_vector(IEEE.numeric_std.resize(unsigned(std_logic_vector(IEEE.numeric_std.resize(unsigned(pixels0_fifo_cap),4))),32));
    reorg_quantize_U0_pixels0_num_data_valid <= std_logic_vector(IEEE.numeric_std.resize(unsigned(std_logic_vector(IEEE.numeric_std.resize(unsigned(pixels0_num_data_valid),4))),32));
    second_convolution_U0_ap_continue <= ap_const_logic_1;
