    second_convolution_U0_sums1_num_data_valid <= std_logic_vector(IEEE.numeric_std.resize(unsigned(std_logic_vector(IEEE.numeric_std.resize(unsigned(sums1_num_data_valid),3))),32));
    serialize_U0_ap_continue <= ap_continue;
    serialize_U0_ap_start <= start_for_serialize_U0_empty_n;
    src_TREADY <= reorg_quantize_U0_src_TREADY;
    start_for_activate_quantize_U0_din <= (0=>ap_const_logic_1, others=>'-');
    start_for_first_convolution_U0_din <= (0=>ap_const_logic_1, others=>'-');
    start_for_second_convolution_U0_din <= (0=>ap_const_logic_1, others=>'-');
    start_for_serialize_U0_din <= (0=>ap_const_logic_1, others=>'-');
    status <= serialize_U0_status;
    status_ap_vld <= serialize_U0_status_ap_vld;
end behav;
